package com.vuelossanitarios.backend.api;

import com.vuelossanitarios.backend.api.dto.AircraftDtos.*;
import com.vuelossanitarios.backend.domain.catalog.*;
import com.vuelossanitarios.backend.domain.person.CommanderProfile;
import com.vuelossanitarios.backend.repository.*;
import com.vuelossanitarios.backend.security.CurrentUser;
import com.vuelossanitarios.backend.service.AircraftAdminService;
import com.vuelossanitarios.backend.service.AuditService;
import java.time.LocalDateTime;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import java.util.*;

@RestController
@RequestMapping("/api/catalogs")
public class CatalogController {
 private final AircraftAdminService aircraft; private final CrewRoleRepository crewRoles; private final AirportRepository airports; private final FlightPriorityRepository priorities; private final ProvinceRepository provinces; private final LocalityRepository localities; private final FlightTypeRepository flightTypes; private final UserRepository users; private final CommanderProfileRepository commanderProfiles; private final CancellationReasonRepository cancellationReasons; private final DocumentTypeRepository documentTypes; private final AuditService audit;
 public CatalogController(AircraftAdminService a,CrewRoleRepository cro, AirportRepository ap, FlightPriorityRepository p, ProvinceRepository pr, LocalityRepository l, FlightTypeRepository ft, UserRepository u, CommanderProfileRepository cp, CancellationReasonRepository cr, DocumentTypeRepository dt, AuditService au){aircraft=a;crewRoles=cro;airports=ap;priorities=p;provinces=pr;localities=l;flightTypes=ft;users=u;commanderProfiles=cp;cancellationReasons=cr;documentTypes=dt;audit=au;}
 @GetMapping("/aircraft") @PreAuthorize("hasAnyRole('DTS','OPERACIONES','CENTRO_OPERACIONES','COMANDANTE','ADMINISTRADOR')") public List<AircraftView> aircraft(){return aircraft.activeList();}
 @GetMapping("/aircraft/admin") @PreAuthorize("hasRole('ADMINISTRADOR')") public List<AircraftAdminView> adminAircraft(){return aircraft.adminList();}
 /** Disponibilidad por intervalo (activa, fuera de vuelo y sin compromisos superpuestos), con los conflictos que la impiden. */
 @GetMapping("/aircraft/availability") @PreAuthorize("hasAnyRole('ADMINISTRADOR','OPERACIONES','CENTRO_OPERACIONES')") public List<AircraftAvailabilityView> aircraftAvailability(@RequestParam @org.springframework.format.annotation.DateTimeFormat(iso=org.springframework.format.annotation.DateTimeFormat.ISO.DATE_TIME) LocalDateTime from,@RequestParam @org.springframework.format.annotation.DateTimeFormat(iso=org.springframework.format.annotation.DateTimeFormat.ISO.DATE_TIME) LocalDateTime to){return aircraft.availability(from,to);}
 @GetMapping("/aircraft/{id}") @PreAuthorize("hasAnyRole('ADMINISTRADOR','OPERACIONES','CENTRO_OPERACIONES')") public AircraftAdminView aircraftDetail(@PathVariable Long id){return aircraft.get(id);}
 @GetMapping("/aircraft/{id}/flights") @PreAuthorize("hasAnyRole('ADMINISTRADOR','OPERACIONES','CENTRO_OPERACIONES')") public List<FlightSummary> aircraftFlights(@PathVariable Long id){return aircraft.flights(id);}
 @GetMapping("/aircraft/{id}/history") @PreAuthorize("hasRole('ADMINISTRADOR')") public List<AircraftHistoryEntry> aircraftHistory(@PathVariable Long id){return aircraft.history(id);}
 @PostMapping("/aircraft") @PreAuthorize("hasRole('ADMINISTRADOR')") public AircraftAdminView createAircraft(@Valid @RequestBody AircraftRequest r,@AuthenticationPrincipal CurrentUser current){return aircraft.create(r,current.id());}
 @PutMapping("/aircraft/{id}") @PreAuthorize("hasRole('ADMINISTRADOR')") public AircraftAdminView updateAircraft(@PathVariable Long id,@Valid @RequestBody AircraftUpdateRequest r,@AuthenticationPrincipal CurrentUser current){return aircraft.update(id,r,current.id());}
 @PostMapping("/aircraft/{id}/active") @PreAuthorize("hasRole('ADMINISTRADOR')") public AircraftAdminView setAircraftActive(@PathVariable Long id,@Valid @RequestBody ActiveRequest r,@AuthenticationPrincipal CurrentUser current){return aircraft.setActive(id,r.activo(),r.motivo(),current.id());}
 @PostMapping("/aircraft/{id}/location") @PreAuthorize("hasAnyRole('ADMINISTRADOR','OPERACIONES','CENTRO_OPERACIONES')") public AircraftAdminView moveAircraft(@PathVariable Long id,@Valid @RequestBody AircraftLocationRequest r,@AuthenticationPrincipal CurrentUser current){return aircraft.move(id,r.locationId(),r.motivo(),current.id());}
 @GetMapping("/crew-roles") @PreAuthorize("hasAnyRole('ADMINISTRADOR','OPERACIONES','CENTRO_OPERACIONES','COMANDANTE')") public List<CrewRoleView> crewRoles(){return crewRoles.findAll().stream().sorted(Comparator.comparing(CrewRole::getNombre)).map(x->new CrewRoleView(x.getCodigo(),x.getNombre())).toList();}
 @GetMapping("/flight-types") @PreAuthorize("hasAnyRole('ADMINISTRADOR','OPERACIONES','CENTRO_OPERACIONES','COMANDANTE')") public List<FlightTypeView> flightTypes(@RequestParam(defaultValue="false") boolean operationalOnly){return flightTypes.findByActivoTrueOrderByNombreAsc().stream().filter(x->!operationalOnly||!"SANITARIO".equals(x.getCodigo())).map(x->new FlightTypeView(x.getCodigo(),x.getNombre())).toList();}
 @GetMapping("/provinces") @PreAuthorize("hasAnyRole('ADMINISTRADOR','DTS','OPERACIONES','CENTRO_OPERACIONES','COMANDANTE')") public List<ProvinceView> provinces(){return provinces.findByActivoTrueOrderByNombreAsc().stream().map(x->new ProvinceView(x.getId(),x.getCodigoOficial(),x.getNombre())).toList();}
 @GetMapping("/localities") @PreAuthorize("hasAnyRole('ADMINISTRADOR','DTS','OPERACIONES','CENTRO_OPERACIONES','COMANDANTE')") public List<LocalityView> localities(@RequestParam Long provinceId,@RequestParam(defaultValue="") String q){return localities.findTop50ByProvincia_IdAndActivoTrueAndNombreContainingIgnoreCaseOrderByNombreAsc(provinceId,q.trim()).stream().map(x->new LocalityView(x.getId(),x.getCodigoOficial(),x.getNombre(),x.getProvincia().getNombre())).toList();}
 @GetMapping("/airports") @PreAuthorize("hasAnyRole('ADMINISTRADOR','DTS','OPERACIONES','CENTRO_OPERACIONES','COMANDANTE')") public List<AirportView> airports(@RequestParam(required=false) Long provinceId,@RequestParam(defaultValue="") String q){List<Airport> found=provinceId==null?airports.findAll().stream().filter(x->Boolean.TRUE.equals(x.getActivo())&&x.getNombre().toLowerCase(Locale.ROOT).contains(q.trim().toLowerCase(Locale.ROOT))).limit(50).toList():airports.findTop50ByActivoTrueAndProvinciaReferencialIdAndNombreContainingIgnoreCaseOrderByNombreAsc(provinceId,q.trim());return found.stream().map(x->new AirportView(x.getId(),x.getCodigoOaci(),x.getCodigoIata(),x.getNombre(),x.getCiudad(),x.getTipo())).toList();}
 @GetMapping("/priorities") @PreAuthorize("hasAnyRole('DTS','OPERACIONES','CENTRO_OPERACIONES','COMANDANTE','ADMINISTRADOR')") public List<PriorityView> priorities(){return priorities.findAll().stream().filter(x->Boolean.TRUE.equals(x.getActivo())).sorted(Comparator.comparing(FlightPriority::getOrden)).map(x->new PriorityView(x.getCodigo(),x.getNombre())).toList();}
 @GetMapping("/cancellation-reasons") @PreAuthorize("hasAnyRole('DTS','OPERACIONES','CENTRO_OPERACIONES','COMANDANTE','ADMINISTRADOR')") public List<CancellationReasonView> cancellationReasons(){return cancellationReasons.findByActivoTrueOrderByOrdenAsc().stream().map(x->new CancellationReasonView(x.getId(),x.getCodigo(),x.getNombre(),x.getCategoria(),x.getOrden())).toList();}
 @GetMapping("/document-types") @PreAuthorize("hasAnyRole('DTS','OPERACIONES','CENTRO_OPERACIONES','COMANDANTE','ADMINISTRADOR')") public List<DocumentTypeView> documentTypes(){return documentTypes.findAll().stream().sorted(Comparator.comparing(DocumentType::getNombre)).map(x->new DocumentTypeView(x.getCodigo(),x.getNombre())).toList();}
 @PostMapping("/commanders/{id}/location") @PreAuthorize("hasAnyRole('ADMINISTRADOR','OPERACIONES','CENTRO_OPERACIONES')") @Transactional public CommanderLocationView moveCommander(@PathVariable Long id,@Valid @RequestBody LocationRequest r,@AuthenticationPrincipal CurrentUser current){var target=users.findWithPersonById(id).orElseThrow(()->new ApiException(org.springframework.http.HttpStatus.NOT_FOUND,"Comandante inexistente"));CommanderProfile profile=target.getPerson().getCommanderProfile();if(profile==null)throw new ApiException(org.springframework.http.HttpStatus.BAD_REQUEST,"El usuario no tiene perfil de comandante");Province next=provinces.findById(r.locationId()).filter(Province::getActivo).orElseThrow(()->new ApiException(org.springframework.http.HttpStatus.BAD_REQUEST,"Seleccione una provincia válida"));Province old=profile.getProvinciaActual();profile.setProvinciaActual(next);audit.record(null,actor(current),"COMMANDER_PROFILE",target.getPerson().getId(),"MANUAL_LOCATION_CHANGE",old==null?null:"{\"provinciaActualId\":"+json(old.getId().toString())+"}","{\"provinciaActualId\":"+json(next.getId().toString())+"}");return new CommanderLocationView(target.getId(),next.getId(),next.getNombre());}
 @PostMapping("/airports") @PreAuthorize("hasRole('ADMINISTRADOR')") @Transactional public AirportView createAirport(@Valid @RequestBody AirportRequest r){Airport x=new Airport();x.setCodigoOaci(blank(r.codigoOaci()));x.setCodigoIata(blank(r.codigoIata()));x.setNombre(r.nombre());x.setCiudad(blank(r.ciudad()));x.setProvincia(blank(r.provincia()));x.setPais(r.pais()==null||r.pais().isBlank()?"Argentina":r.pais());airports.save(x);return new AirportView(x.getId(),x.getCodigoOaci(),x.getCodigoIata(),x.getNombre(),x.getCiudad(),x.getTipo());}
 private String blank(String value){return value==null||value.isBlank()?null:value.trim();}
 private com.vuelossanitarios.backend.domain.user.User actor(CurrentUser current){return users.findById(current.id()).orElseThrow(()->new ApiException(org.springframework.http.HttpStatus.NOT_FOUND,"Usuario inexistente"));}
 private String json(String value){return value==null?null:"\""+value+"\"";}
 public record LocationRequest(@NotNull Long locationId){} public record CommanderLocationView(Long comandanteId,Long provinciaActualId,String provinciaActual){}
 public record AirportRequest(@Size(max=4) String codigoOaci,@Size(max=3) String codigoIata,@NotBlank @Size(max=150) String nombre,@Size(max=100) String ciudad,@Size(max=100) String provincia,@Size(max=100) String pais){}
 public record CrewRoleView(String codigo,String nombre){} public record FlightTypeView(String codigo,String nombre){} public record ProvinceView(Long id,String codigoOficial,String nombre){} public record LocalityView(Long id,String codigoOficial,String nombre,String provincia){} public record AirportView(Long id,String codigoOaci,String codigoIata,String nombre,String ciudad,String tipo){} public record PriorityView(String codigo,String nombre){} public record DocumentTypeView(String codigo,String nombre){} public record CancellationReasonView(Long id,String codigo,String nombre,String categoria,Short orden){}
}
